function setup() {
  createCanvas(500, 700, SVG);
  stroke(32);
  // noLoop() removed for animation
}

function draw() {
	background(222);
  const MAR = 50;
	const ww = 100;
	strokeWeight(3)
	noFill()
	for (let xx = 0; xx < ww; xx += 5) {
		stroke(random(["black", "darkred", "navy", "darkorange", "darkgreen", "blue"]))
		stroke(0); strokeWeight(2*(1-xx/ww))
		let lx, ly;
		const stps = 200;
		beginShape();
		for (let ys=0; ys < stps; ys++) {		
			const f = ys / stps;
			const x = width/2;
			const y = map(f, 0, 1, MAR, height-MAR);
			const scl = map(xx, 0, ww, 0.01, 0.02);
			const dx = (noise(1.23+x*scl, 3.21+y*scl, frameCount)-0.5) * width * 0.75 * sin(PI*(f*0.8+0.1));
			// if (ys > 0) line(lx, ly, x + dx, y);
			vertex(x + dx, y);
			lx = x + dx;
			ly = y;
		}
		endShape();
		strokeWeight(1)
	}  
}

function mousePressed() {
	if (mouseButton === LEFT) redraw();
}

function keyPressed() {
	if (key === 's' || key === 'S') {
		save("mySketch.svg"); // Save the canvas as SVG
	}
}
